import fs from "fs";
const alpha = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
const SQ = String.fromCharCode(39);
const BS = String.fromCharCode(92);
function pyrepr(c) {
  const cp = c.codePointAt(0);
  if (c === SQ) return '"' + SQ + '"';
  let body;
  if (c === BS) body = BS + BS;
  else if (cp === 9) body = BS + "t";
  else if (cp === 10) body = BS + "n";
  else if (cp === 13) body = BS + "r";
  else if (cp < 0x20 || cp === 0x7f) body = BS + "x" + cp.toString(16).padStart(2, "0");
  else body = c;
  return SQ + body + SQ;
}
const out = [];
for (let i = 1; i <= 127; i++) {
  const c = String.fromCharCode(i);
  let exp;
  if (alpha.includes(c)) exp = "RC0";
  else if (c === "-") exp = "RC2";
  else exp = "ValueError: Invalid character " + pyrepr(c);
  out.push(i + "\t" + exp);
}
fs.writeFileSync("/tmp/exp_ascii.tsv", out.join("\n") + "\n");

